// ============================================================================
//  Cross-language check: the Dart DECODER must match the firmware's C++
//  ENCODER exactly. These two are written in different languages, compiled by
//  different toolchains, and never run on the same machine — if they drift,
//  every note arrives as noise and nothing else in the app would tell you.
//
//  The vectors below were produced by running the REAL firmware encoder
//  (jota/firmware/src/audio/adpcm.cpp) on the host over a known 440 Hz tone.
//  Regenerate them if that encoder ever changes.
// ============================================================================
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:jota/audio/adpcm.dart';

const encoded = <int>[0,0,52,0,55,50,35,18,128,185,205,188,204,187,187,187,170,136,50,69,68,67,67,35,35,18,129,169,204,204,203,203,186,171,170,136,33,99,83,67,67,35,35,19,1,168,188,190,188,188,172,171,170,137,32,82,52,68,67,35,51,19,2,152,219,204,203,188,187,187,187,153,16,83,68,52,52,52,50,34,2,144,202,204,188,188,172,187,170,154,0,50,54,53,52,36,51,35,17,128,201,235,203,203,203,186,170,154,8,49,68,53,52,67,51,35,18,129,185,220,188,204,187,187,172,169,8,32,68,83,67,67,35,35,34,0,153,204,204,203,187,188,171,170,137,17,68,83,52,67,67,34,18,1,152,203,204,219,187,203,186,170,137,16,67,84,67,51,52,51,34,2,144,219,188,189,188,188,186,170,153,24,66,68,52,52,36,51,34,18,136,186,190,189,188,172,187,171,153,8,65,99,67,67,67,50,34,18,128,185,204,189,188,203,187,171,154,9,49,84,52,68,51,51,36,17,129,168,204,219,203,203,186,171,170,136,32,68,68,67,51,52,35,34,1,153,204,219,188,172,203,170,154,137,16,3];
const pcmRef = <int>[0,1891,3726,5450,7011,8364,9468,10289,10805,10998,10864,10406,9639,8584,7274,5747,4049,2230,345,-1549,-3399,-5147,-6741,-8135,-9287,-10162,-10735,-10987,-10913,-10513,-9801,-8796,-7530,-6039,-4368,-2567,-690,1207,3068,4839,6465,7899,9097,10025,10654,10966,10951,10610,9953,8999,7778,6325,4683,2902,1035,-863,-2735,-4526,-6182,-7655,-8899,-9878,-10563,-10933,-10978,-10696,-10095,-9193,-8018,-6604,-4993,-3234,-1378,518,2399,4209,5894,7403,8691,9721,10461,10890,10994,10771,10227,9379,8251,6877,5299,3563,1720,-172,-2061,-3888,-5599,-7143,-8475,-9554,-10349,-10836,-11000,-10836,-10349,-9554,-8475,-7143,-5599,-3888,-2061,-172,1720,3563,5299,6877,8251,9379,10227,10771,10994,10890,10461,9721,8691,7403,5894,4209,2399,518,-1378,-3234,-4993,-6604,-8018,-9193,-10095,-10696,-10978,-10933,-10563,-9878,-8899,-7655,-6182,-4526,-2735,-863,1035,2902,4683,6325,7778,8999,9953,10610,10951,10966,10654,10025,9097,7899,6465,4839,3068,1207,-690,-2567,-4368,-6039,-7530,-8796,-9801,-10513,-10913,-10987,-10735,-10162,-9287,-8135,-6741,-5147,-3399,-1549,345,2230,4049,5747,7274,8584,9639,10406,10864,10998,10805,10289,9468,8364,7011,5450,3726,1891,0,-1891,-3726,-5450,-7011,-8364,-9468,-10289,-10805,-10998,-10864,-10406,-9639,-8584,-7274,-5747,-4049,-2230,-345,1549,3399,5147,6741,8135,9287,10162,10735,10987,10913,10513,9801,8796,7530,6039,4368,2567,690,-1207,-3068,-4839,-6465,-7899,-9097,-10025,-10654,-10966,-10951,-10610,-9953,-8999,-7778,-6325,-4683,-2902,-1035,863,2735,4526,6182,7655,8899,9878,10563,10933,10978,10696,10095,9193,8018,6604,4993,3234,1378,-518,-2399,-4209,-5894,-7403,-8691,-9721,-10461,-10890,-10994,-10771,-10227,-9379,-8251,-6877,-5299,-3563,-1720,172,2061,3888,5599,7143,8475,9554,10349,10836,11000,10836,10349,9554,8475,7143,5599,3888,2061,172,-1720,-3563,-5299,-6877,-8251,-9379,-10227,-10771,-10994,-10890,-10461,-9721,-8691,-7403,-5894,-4209,-2399,-518,1378,3234,4993,6604,8018,9193,10095,10696,10978,10933,10563,9878,8899,7655,6182,4526,2735,863,-1035,-2902,-46