void main() {
  test('decoder reproduces the firmware encoder within ADPCM error bounds', () {
    final decoded = Adpcm.decode(Uint8List.fromList(encoded));

    expect(encoded.length, Adpcm.blockBytes);
    expect(decoded.length, greaterThanOrEqualTo(pcmRef.length - 2));

    // The block header carries sample 0 verbatim, so it must be exact. If the
    // header layout ever disagreed, this is the first thing that would fail.
    expect(decoded[0], pcmRef[0]);

    // Everything after that is lossy, so judge it by signal-to-noise rather
    // than equality. IMA ADPCM on a clean tone should land well above 20 dB;
    // a real mismatch (wrong tables, wrong nibble order) collapses this to
    // near 0 dB or negative.
    double signal = 0, noise = 0;
    final n = math.min(decoded.length, pcmRef.length);
    for (var i = 0; i < n; i++) {
      final s = pcmRef[i].toDouble();
      final e = decoded[i].toDouble() - s;
      signal += s * s;
      noise += e * e;
    }
    final snrDb = 10 * (math.log(signal / noise) / math.ln10);
    expect(snrDb, greaterThan(20.0), reason: 'SNR ${snrDb.toStringAsFixed(1)} dB');
  });

  test('block geometry agrees with the firmware', () {
    // These four numbers are duplicated across the language boundary; if the
    // firmware changes any of them the protocol silently breaks.
    expect(Adpcm.blockBytes, 256);
    expect(Adpcm.blockSamples, 504);
    expect(Adpcm.headerBytes, 4);
    expect(Adpcm.sampleRate, 16000);
  });
}
